func testHistoricoContabilToManyRemoveOpHisctbLancamentoContabils(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a HistoricoContabil
	var b, c, d, e LancamentoContabil

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, historicoContabilDBTypes, false, strmangle.SetComplement(historicoContabilPrimaryKeyColumns, historicoContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LancamentoContabil{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, lancamentoContabilDBTypes, false, strmangle.SetComplement(lancamentoContabilPrimaryKeyColumns, lancamentoContabilColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddHisctbLancamentoContabils(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.HisctbLancamentoContabils().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveHisctbLancamentoContabils(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.HisctbLancamentoContabils().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.HisctbID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.HisctbID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Hisctb != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Hisctb != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Hisctb != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Hisctb != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.HisctbLancamentoContabils) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.HisctbLancamentoContabils[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.HisctbLancamentoContabils[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

